+  it("matches scattered characters in order", () => {
+    // "hd" matches 'h' at 0 and 'd' at 2 in "Heading"
+    const score = fuzzyScore("Heading", "hd");
+    expect(score).not.toBeNull();
+    expect(score!).toBeGreaterThan(0);
+  });
